#include <dt-bindings/zmk/matrix_transform.h>

/ {
    chosen { zmk,kscan = &kscan0; zmk,matrix-transform = &default_transform; };
    default_transform: keymap_transform_0 {
        compatible = "zmk,matrix-transform";
        columns = <10>;
        rows = <5>;
        map = <RC(0,0) RC(0,1) RC(0,2) RC(0,3) RC(0,4) RC(1,0) RC(1,1) RC(1,2) RC(1,3) RC(1,4) RC(2,0) RC(2,1) RC(2,2) RC(2,3) RC(2,4) RC(3,0) RC(3,1) RC(3,2) RC(3,3) RC(3,4) RC(4,0) RC(0,5) RC(0,6) RC(0,7) RC(0,8) RC(0,9) RC(1,5) RC(1,6) RC(1,7) RC(1,8) RC(1,9) RC(2,5) RC(2,6) RC(2,7) RC(2,8) RC(2,9) RC(3,5) RC(3,6) RC(3,7) RC(3,8) RC(3,9) RC(4,5)>;
    };
    kscan0: kscan {
        compatible = "zmk,kscan-gpio-matrix";
        diode-direction = "col2row";
    };
};

#include "bara.dtsi"

&kscan0 {
    row-gpios
        = <&gpio1 6 (GPIO_ACTIVE_HIGH | GPIO_PULL_DOWN)>
        , <&gpio1 4 (GPIO_ACTIVE_HIGH | GPIO_PULL_DOWN)>
        , <&gpio0 11 (GPIO_ACTIVE_HIGH | GPIO_PULL_DOWN)>
        , <&gpio0 9 (GPIO_ACTIVE_HIGH | GPIO_PULL_DOWN)>
        , <&gpio0 10 (GPIO_ACTIVE_HIGH | GPIO_PULL_DOWN)>;
    col-gpios
        = <&gpio1 0 (GPIO_ACTIVE_HIGH | GPIO_PULL_DOWN)>
        , <&gpio0 24 (GPIO_ACTIVE_HIGH | GPIO_PULL_DOWN)>
        , <&gpio0 22 (GPIO_ACTIVE_HIGH | GPIO_PULL_DOWN)>
        , <&gpio0 20 (GPIO_ACTIVE_HIGH | GPIO_PULL_DOWN)>
        , <&gpio1 11 (GPIO_ACTIVE_HIGH | GPIO_PULL_DOWN)>;
};

/* OLED on I2C: SDA P0.29-LF, SCL P0.02-LF */
&i2c0 { status = "okay"; oled: ssd1306@3c { compatible = "solomon,ssd1306fb"; reg = <0x3c>; }; };

#include "bara.dtsi"

&kscan0 {
    row-gpios
        = <&gpio0 9 (GPIO_ACTIVE_HIGH | GPIO_PULL_DOWN)>
        , <&gpio0 10 (GPIO_ACTIVE_HIGH | GPIO_PULL_DOWN)>
        , <&gpio1 11 (GPIO_ACTIVE_HIGH | GPIO_PULL_DOWN)>
        , <&gpio1 13 (GPIO_ACTIVE_HIGH | GPIO_PULL_DOWN)>
        , <&gpio1 6 (GPIO_ACTIVE_HIGH | GPIO_PULL_DOWN)>;
    col-gpios
        = <&gpio1 15 (GPIO_ACTIVE_HIGH | GPIO_PULL_DOWN)>
        , <&gpio0 2 (GPIO_ACTIVE_HIGH | GPIO_PULL_DOWN)>
        , <&gpio0 29 (GPIO_ACTIVE_HIGH | GPIO_PULL_DOWN)>
        , <&gpio1 4 (GPIO_ACTIVE_HIGH | GPIO_PULL_DOWN)>
        , <&gpio0 31 (GPIO_ACTIVE_HIGH | GPIO_PULL_DOWN)>;
};
&default_transform { col-offset = <5>; };

#include <behaviors.dtsi>
#include <dt-bindings/zmk/keys.h>

/ {
    keymap {
        compatible = "zmk,keymap";
        base {
            bindings = <
                &kp Q  &kp W  &kp E  &kp R  &kp T  &kp Y  &kp U  &kp I  &kp O  &kp P  &kp A  &kp S  &kp D  &kp F  &kp G  &kp H  &kp J  &kp K  &kp LGUI  &kp SPACE  &kp LSHFT
                &kp L  &kp SEMI  &kp Z  &kp X  &kp C  &kp V  &kp B  &kp N  &kp M  &kp COMMA  &kp DOT  &kp FSLH  &kp N1  &kp N2  &kp N3  &kp N4  &kp N5  &kp N6  &kp RET  &kp BSPC  &kp LALT
            >;
        };
    };
};
